function deepClone(x){ return JSON.parse(JSON.stringify(x)); }
function mergeScopes(value,required){const set=new Set(String(value||'').split(/\s+/).filter(Boolean));for(const x of String(required||'').split(/\s+/).filter(Boolean))set.add(x);return [...set].join(' ');}
