function requestBaseUrl(req,config=loadConfig()){if(config.publicBaseUrl)return config.publicBaseUrl;const proto=String(req.headers['x-forwarded-proto']||'http').split(',')[0].trim();const host=String(req.headers['x-forwarded-host']||req.headers.host||`localhost:${config.port}`).split(',')[0].trim();return `${proto}://${host}`;}
function baseGiveaway(roundNumber=1){return {roundNumber,title:'SOVARA GIFT',prizeRub:5000,ticketCost:300,maxTickets:10,minParticipants:10,durationDays:30,isTest:false,testDurationMinutes:null,testRestore:null,startedAt:null,endsAt:null,winner:null,prizeDeliveredAt:null,completedAt:null,archivedAt:null};}
function baseState(){ return {version:11,giveaway:baseGiveaway(1),nextRound:{prizeRub:5000,ticketCost:300,maxTickets:10,minParticipants:10,durationDays:30},giveawayHistory:[],admins:[],settings:{pointsPerMinute:1,pointsPerMessage:1,watchtimePollMinutes:5,messagePointsEnabled:true,watchtimePointsEnabled:true,countMessagesOffline:false,chatCooldownSeconds:30,globalPointsPaused:false},users:{},processedMessages:{},audit:[]}; }
