function cleanTwitchLogin(x){return esc(x).replace(/^https?:\/\/(www\.)?twitch\.tv\//i,'').replace(/^@/,'').replace(/\/$/,'').toLowerCase();}
function normalizeAdminEntry(a){a=a||{};return {twitchUserId:esc(a.twitchUserId),login:cleanTwitchLogin(a.login),displayName:esc(a.displayName||a.login),avatar:esc(a.avatar),addedAt:Number(a.addedAt)||now(),addedBy:esc(a.addedBy)};}
