function defaultProfile(){return {prizeType:'',steamLogin:'',steamCurrency:'RUB',steamFriendCode:'',steamGameUrl:'',ozonEmail:'',donationGame:'',donationAccount:'',contactVk:'',contactTelegram:'',prizeTermsAcceptedFor:'',prizeTermsVersion:''};}
function defaultSettings(){return {pointsPerMinute:1,pointsPerMessage:1,watchtimePollMinutes:5,messagePointsEnabled:true,watchtimePointsEnabled:true,countMessagesOffline:false,chatCooldownSeconds:30,globalPointsPaused:false};}
function normalizeRoundConfig(x,fallback={}){x=Object.assign({},fallback||{},x||{});return {prizeRub:Math.max(100,Math.min(1000000,Math.floor(Number(x.prizeRub)||5000))),ticketCost:Math.max(1,Math.min(1000000,Math.floor(Number(x.ticketCost)||300))),maxTickets:Math.max(1,Math.min(100,Math.floor(Number(x.maxTickets)||10))),minParticipants:Math.max(1,Math.min(10000,Math.floor(Number(x.minParticipants)||10))),durationDays:Math.max(1,Math.min(365,Math.floor(Number(x.durationDays)||30)))};}
function normalizeUser(u){
  u.points=Number.isFinite(Number(u.points))?Math.max(0,Math.floor(Number(u.points))):0;
  u.tickets=Number.isFinite(Number(u.tickets))?Math.max(0,Math.floor(Number(u.tickets))):0;
  u.totalWatchMinutes=Number.isFinite(Number(u.totalWatchMinutes))?Math.max(0,Math.floor(Number(u.totalWatchMinutes))):0;
  u.profile=Object.assign(defaultProfile(),u.profile||{});
  u.chatHistory=Array.isArray(u.chatHistory)?u.chatHistory.slice(-200):[];
  u.pointsPausedUntil=Number.isFinite(Number(u.pointsPausedUntil))?Math.max(0,Number(u.pointsPausedUntil)):0;
  u.winnerBlacklisted=!!u.winnerBlacklisted;
  u.winnerBlacklistedAt=Number.isFinite(Number(u.winnerBlacklistedAt))?Math.max(0,Number(u.winnerBlacklistedAt)):0;
  u.lastChatPointAt=Number.isFinite(Number(u.lastChatPointAt))?Math.max(0,Number(u.lastChatPointAt)):0;
  u.isFollower=u.isFollower===true?true:(u.isFollower===false?false:null);
  u.followerCheckedAt=Number.isFinite(Number(u.followerCheckedAt))?Math.max(0,Number(u.followerCheckedAt)):0;
  u.createdAt=Number(u.createdAt)||now();u.updatedAt=Number(u.updatedAt)||now();
  return u;
}
function normalizeGiveaway(g){
  const round=Math.max(1,Math.floor(Number(g&&g.roundNumber)||1));
  g=Object.assign(baseGiveaway(round),g||{});g.roundNumber=round;
  for(const k of ['startedAt','endsAt','prizeDeliveredAt','completedAt','archivedAt'])g[k]=Number(g[k])||null;
  g.isTest=!!g.isTest;g.testDurationMinutes=g.isTest?Math.max(1,Math.floor(Number(g.testDurationMinutes)||5)):null;g.testRestore=g.isTest&&g.testRestore&&typeof g.testRestore==='object'?g.testRestore:null;
  return g;
}
function migrateState(s){
  const sourceVersion=Number(s&&s.version)||0;
  const b=baseState();s=Object.assign(b,s||{});s.giveaway=normalizeGiveaway(s.giveaway);s.nextRound=normalizeRoundConfig(s.nextRound,{prizeRub:s.giveaway.prizeRub,ticketCost:s.giveaway.ticketCost,maxTickets:s.giveaway.maxTickets,minParticipants:s.giveaway.minParticipants,durationDays:s.giveaway.durationDays});s.giveawayHistory=Array.isArray(s.giveawayHistory)?s.giveawayHistory.slice(0,100):[];s.admins=Array.isArray(s.admins)?s.admins.map(normalizeAdminEntry).filter(a=>a.login).slice(0,20):[];s.settings=Object.assign(defaultSettings(),s.settings||{});s.settings.chatCooldownSeconds=Math.max(0,Math.min(3600,Math.floor(Number(s.settings.chatCooldownSeconds)||0)));s.settings.globalPointsPaused=!!s.settings.globalPointsPaused;s.users=s.users||{};s.processedMessages=s.processedMessages||{};s.audit=Array.isArray(s.audit)?s.audit.slice(-2000):[];
  Object.keys(s.users).forEach(k=>normalizeUser(s.users[k]));
  // v1.5.6 could incorrectly mark all legacy users as non-followers when the follower list was unavailable.
  // Reset only that migration once; the next successful Twitch sync will establish the real status.
  if(sourceVersion<11){for(const u0 of Object.values(s.users)){const u=normalizeUser(u0);u.isFollower=null;u.followerCheckedAt=0;}}
  s.version=11;
  // Old prototype could already have a 7-day end date. Upgrade it to 30 days from the original start.
  if(!s.giveaway.isTest&&s.giveaway.startedAt && s.giveaway.durationDays===30){const desired=s.giveaway.startedAt+30*86400000;if(!s.giveaway.endsAt||s.giveaway.endsAt<s.giveaway.startedAt+29*86400000)s.giveaway.endsAt=desired;}
  cleanupProcessed(s);return s;
}
function loadState(){return migrateState(jsonRead(STATE_FILE,baseState()));}
function saveState(s){jsonWrite(STATE_FILE,migrateState(s));}
function cleanupProcessed(s){const cut=now()-30*86400000;const keys=Object.keys(s.processedMessages||{}).sort((a,b)=>(s.processedMessages[b]||0)-(s.processedMessages[a]||0));keys.forEach((k,i)=>{if(i>=10000||s.processedMessages[k]<cut)delete s.processedMessages[k];});}
function roundDurationMs(g){return g&&g.isTest?Math.max(1,Math.floor(Number(g.testDurationMinutes)||5))*60000:Math.max(1,Number(g&&g.durationDays||30))*86400000;}
function backupList(){try{return fs.readdirSync(BACKUP_DIR).filter(x=>/^backup-.*\.json$/.test(x)).map(name=>{const file=path.join(BACKUP_DIR,name),st=fs.statSync(file);return {name,createdAt:st.mtimeMs,size:st.size};}).sort((a,b)=>b.createdAt-a.createdAt);}catch{return []}}
function pruneBackups(){for(const x of backupList().slice(BACKUP_KEEP)){try{fs.unlinkSync(path.join(BACKUP_DIR,x.name));}catch{}}}
function createBackup(reason='manual',actor=null){fs.mkdirSync(BACKUP_DIR,{recursive:true});const stamp=new Date().toISOString().replace(/[:.]/g,'-'),name=`backup-${stamp}-${String(reason).replace(/[^a-z0-9_-]+/gi,'-').slice(0,32)}.json`,file=path.join(BACKUP_DIR,name);const payload={version:1,createdAt:now(),reason,actor:actor||null,config:jsonRead(CONFIG_FILE,{}),state:migrateState(jsonRead(STATE_FILE,baseState()))};fs.writeFileSync(file,JSON.stringify(payload,null,2),'utf8');try{fs.chmodSync(file,0o600)}catch{}pruneBackups();return {name,createdAt:payload.createdAt,size:fs.statSync(file).size,reason};}
function getBackupFile(name){name=String(name||'');if(!/^backup-[A-Za-z0-9_.-]+\.json$/.test(name))return null;const file=path.join(BACKUP_DIR,path.basename(name));return fs.existsSync(file)?file:null;}
function maybeAutoBackup(){const last=backupList()[0];if(!last||now()-last.createdAt>20*3600000){try{return createBackup('auto')}catch(e){console.error('Backup failed:',e.message)}}return last||null}
function startBackupLoop(){if(runtime.backupTimer)clearInterval(runtime.backupTimer);maybeAutoBackup();runtime.backupTimer=setInterval(()=>{try{createBackup('auto')}catch(e){console.error('Backup failed:',e.message)}},24*3600000);}
function captureTestRestore(state){const g=state.giveaway,userRound={};for(const [uid,u0] of Object.entries(state.users)){const u=normalizeUser(u0);userRound[uid]={points:u.points,tickets:u.tickets,totalWatchMinutes:u.totalWatchMinutes,lastChatPointAt:u.lastChatPointAt||0};}return {giveaway:{title:g.title,prizeRub:g.prizeRub,ticketCost:g.ticketCost,maxTickets:g.maxTickets,minParticipants:g.minParticipants,durationDays:g.durationDays},userRound,processedMessages:deepClone(state.processedMessages||{})};}
function restoreAfterTest(state){const old=state.giveaway,restore=old.testRestore||{},cfg=restore.giveaway||{},next=baseGiveaway(Number(old.roundNumber||1));for(const k of ['title','prizeRub','ticketCost','maxTickets','minParticipants','durationDays'])if(cfg[k]!==undefined)next[k]=cfg[k];for(const [uid,u0] of Object.entries(state.users)){const u=normalizeUser(u0),r=restore.userRound&&restore.userRound[uid];u.points=r?Number(r.points)||0:0;u.tickets=r?Number(r.tickets)||0:0;u.totalWatchMinutes=r?Number(r.totalWatchMinutes)||0:0;u.lastChatPointAt=r?Number(r.lastChatPointAt)||0:0;u.updatedAt=now();}state.processedMessages=restore.processedMessages&&typeof restore.processedMessages==='object'?restore.processedMessages:{};state.giveaway=next;return next;}
function ticketCount(points,g){return Math.min(Number(g.maxTickets||10),Math.floor(Math.max(0,Number(points)||0)/Number(g.ticketCost||300)));}
function syncTickets(u,g){u.tickets=ticketCount(u.points,g);}
function getUser(state,twitch){const key=String(twitch.id);if(!state.users[key])state.users[key]=normalizeUser({twitchUserId:key,login:twitch.login||key,displayName:twitch.displayName||twitch.login||key,avatar:twitch.avatar||'',points:0,tickets:0,totalWatchMinutes:0,profile:defaultProfile(),chatHistory:[],pointsPausedUntil:0,createdAt:now(),updatedAt:now()});const u=normalizeUser(state.users[key]);u.login=twitch.login||u.login;u.displayName=twitch.displayName||u.displayName;u.avatar=twitch.avatar||u.avatar;if(isStaffUser(state,u)){u.points=0;u.tickets=0;u.totalWatchMinutes=0;}else syncTickets(u,state.giveaway);u.updatedAt=now();return u;}
function getOrCreateChatUser(state,e){return getUser(state,{id:String(e.userId),login:e.login||String(e.userId),displayName:e.displayName||e.login||String(e.userId),avatar:''});}
function profileValidation(profile){const p=Object.assign(defaultProfile(),profile||{}),errors={};const tg=esc(p.contactTelegram),vk=esc(p.contactVk);if(!tg&&!vk)errors.contact='Укажите хотя бы Telegram или VK.';if(tg&&!/^@?[A-Za-z0-9_]{5,32}$/.test(tg))errors.contactTelegram='Telegram: @username или username.';if(vk&&!/^(https?:\/\/)?(www\.)?vk\.(com|ru)\/[A-Za-z0-9_.-]+\/?$/i.test(vk))errors.contactVk='Укажите ссылку на профиль VK.';const allowed=['steam_balance','steam_game','ozon','game_donation'];if(!allowed.includes(p.prizeType))errors.prizeType='Выберите желаемый приз.';if(p.prizeType==='steam_balance'){if(!/^[^\x00-\x1f\x7f]{2,64}$/.test(esc(p.steamLogin)))errors.steamLogin='Укажите Steam login.';if(!['RUB','KZT','USD','EUR'].includes(esc(p.steamCurrency).toUpperCase()))errors.steamCurrency='Выберите валюту из списка.';}if(p.prizeType==='steam_game'){if(!/^\d{5,12}$/.test(esc(p.steamFriendCode)))errors.steamFriendCode='Код дружбы должен состоять из цифр.';if(!/^https:\/\/store\.steampowered\.com\/app\/\d+/i.test(esc(p.steamGameUrl)))errors.steamGameUrl='Нужна ссылка на игру в Steam Store.';}if(p.prizeType==='ozon'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(esc(p.ozonEmail)))errors.ozonEmail='Укажите корректную почту.';if(p.prizeType==='game_donation'){if(esc(p.donationGame).length<2)errors.donationGame='Укажите игру.';if(esc(p.donationAccount).length<2)errors.donationAccount='Укажите игровой ID / ник / сервер.';}if(['steam_game','game_donation'].includes(p.prizeType)&&(esc(p.prizeTermsAcceptedFor)!==p.prizeType||esc(p.prizeTermsVersion)!==PRIZE_TERMS_VERSION))errors.prizeTerms='Прочитайте и подтвердите условия выбранного приза.';return {ok:Object.keys(errors).length===0,errors};}
function profileSaveValidation(profile){const p=Object.assign(defaultProfile(),profile||{}),errors={};const tg=esc(p.contactTelegram),vk=esc(p.contactVk),type=esc(p.prizeType);if(tg&&!/^@?[A-Za-z0-9_]{5,32}$/.test(tg))errors.contactTelegram='Telegram: @username, username или ссылка t.me.';if(vk&&!/^(https?:\/\/)?(www\.)?vk\.(com|ru)\/[A-Za-z0-9_.-]+\/?$/i.test(vk))errors.contactVk='Укажите корректную ссылку на профиль VK.';if(type&&!['steam_balance','steam_game','ozon','game_donation'].includes(type))errors.prizeType='Неизвестный вариант приза.';if(type==='steam_balance'&&esc(p.steamLogin)&&!/^[^\x00-\x1f\x7f]{2,64}$/.test(esc(p.steamLogin)))errors.steamLogin='Steam login указан некорректно.';if(type==='steam_balance'&&esc(p.steamCurrency)&&!['RUB','KZT','USD','EUR'].includes(esc(p.steamCurrency).toUpperCase()))errors.steamCurrency='Выберите валюту из списка.';if(type==='steam_game'&&esc(p.steamFriendCode)&&!/^\d{5,12}$/.test(esc(p.steamFriendCode)))errors.steamFriendCode='Код дружбы Steam должен состоять из 5–12 цифр.';if(type==='steam_game'&&esc(p.steamGameUrl)&&!/^https:\/\/store\.steampowered\.com\/app\/\d+/i.test(esc(p.steamGameUrl)))errors.steamGameUrl='Нужна ссылка на игру в Steam Store.';if(type==='ozon'&&esc(p.ozonEmail)&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(esc(p.ozonEmail)))errors.ozonEmail='Укажите корректную почту.';if(type==='game_donation'&&esc(p.donationGame)&&esc(p.donationGame).length<2)errors.donationGame='Название игры слишком короткое.';if(type==='game_donation'&&esc(p.donationAccount)&&esc(p.donationAccount).length<2)errors.donationAccount='Данные игрового аккаунта слишком короткие.';if(['steam_game','game_donation'].includes(type)&&(esc(p.prizeTermsAcceptedFor)!==type||esc(p.prizeTermsVersion)!==PRIZE_TERMS_VERSION))errors.prizeTerms='Прочитайте и подтвердите условия выбранного приза.';return {ok:Object.keys(errors).length===0,errors};}
function prizeLabel(type){return ({steam_balance:'Пополнение Steam',steam_game:'Игра в Steam',ozon:'Сертификат Ozon',game_donation:'Донат в игру'})[type]||'Не выбран';}
function followStatus(u){return u&&u.isFollower===true?'FOLLOW':u&&u.isFollower===false?'NO_FOLLOW':'UNKNOWN';}
function publicUser(u){const v=profileValidation(u.profile);return {twitchUserId:u.twitchUserId,login:u.login,displayName:u.displayName,avatar:u.avatar||'',points:u.points,tickets:u.tickets,isFollower:u.isFollower===true,followStatus:followStatus(u),participating:u.isFollower===true&&v.ok&&u.tickets>0};}
function privateUser(u){const v=profileValidation(u.profile);return Object.assign(publicUser(u),{profile:u.profile,profileComplete:v.ok,profileErrors:v.errors,followerCheckedAt:u.followerCheckedAt||0,totalWatchMinutes:u.totalWatchMinutes,prizeLabel:prizeLabel(u.profile.prizeType),pointsPausedUntil:u.pointsPausedUntil||0,isPointsPaused:(u.pointsPausedUntil||0)>now(),winnerBlacklisted:!!u.winnerBlacklisted,winnerBlacklistedAt:u.winnerBlacklistedAt||0,chatCount:u.chatHistory.length,lastChat:u.chatHistory.length?u.chatHistory[u.chatHistory.length-1]:null});}
