function drawWinner(state){const pool=winnerPool(state);const total=pool.reduce((n,u)=>n+u.tickets,0);if(total<=0)return null;let pick=crypto.randomInt(1,total+1),cursor=0;for(const u of pool){cursor+=u.tickets;if(pick<=cursor)return {twitchUserId:u.twitchUserId,login:u.login,displayName:u.displayName,tickets:u.tickets,points:u.points,drawTicket:pick,totalEligibleTickets:total,drawnAt:now()};}return null;}
function giveawayPhase(g){if(g.completedAt)return 'COMPLETED';if(g.winner)return g.prizeDeliveredAt?'PRIZE_DELIVERED':'WINNER_SELECTED';if(g.startedAt&&g.endsAt&&now()>=g.endsAt)return 'READY_TO_DRAW';if(g.startedAt)return 'RUNNING';return 'WAITING';}
