function publicGiveaway(state){const g=state.giveaway,safe=Object.assign({},g);delete safe.testRestore;return Object.assign(safe,{winner:publicWinner(g.winner),phase:giveawayPhase(g),eligibleParticipants:countEligible(state),accrualOpen:accrualOpen(state),profileEditsLocked:profileEditsLocked(state)});}
function adminGiveaway(state){const g=state.giveaway,safe=Object.assign({},g);delete safe.testRestore;return Object.assign(safe,{phase:giveawayPhase(g),eligibleParticipants:countEligible(state),accrualOpen:accrualOpen(state),profileEditsLocked:profileEditsLocked(state)});}
function winnerSnapshot(state,winner){const u=normalizeUser(state.users[String(winner.twitchUserId)]);return Object.assign({},winner,{points:u.points,avatar:u.avatar||'',prizeLabel:prizeLabel(u.profile.prizeType),profile:deepClone(u.profile)});}
function archiveSnapshot(state){const g=state.giveaway,participants=eligibleUsers(state);return {roundNumber:g.roundNumber,title:g.title,prizeRub:g.prizeRub,ticketCost:g.ticketCost,maxTickets:g.maxTickets,minParticipants:g.minParticipants,durationDays:g.durationDays,isTest:!!g.isTest,startedAt:g.startedAt,endsAt:g.endsAt,participantsCount:participants.length,totalTickets:participants.reduce((n,u)=>n+Number(u.tickets||0),0),winnerPoolTickets:winnerPool(state).reduce((n,u)=>n+Number(u.tickets||0),0),winner:deepClone(g.winner),prizeDeliveredAt:g.prizeDeliveredAt,completedAt:g.completedAt,archivedAt:g.archivedAt||now()};}
function publicArchiveEntry(x){const w=x&&x.winner||{};return {roundNumber:Number(x&&x.roundNumber)||0,title:String(x&&x.title||'SOVARA GIFT'),prizeRub:Number(x&&x.prizeRub)||0,startedAt:Number(x&&x.startedAt)||null,endsAt:Number(x&&x.endsAt)||null,completedAt:Number(x&&x.completedAt)||null,participantsCount:Number(x&&x.participantsCount)||0,totalTickets:Number(x&&x.totalTickets)||0,winner:w&&w.twitchUserId?{twitchUserId:String(w.twitchUserId),login:String(w.login||''),displayName:String(w.displayName||w.login||''),avatar:String(w.avatar||''),tickets:Number(w.tickets)||0,drawTicket:Number(w.drawTicket)||0,totalEligibleTickets:Number(w.totalEligibleTickets)||0,drawnAt:Number(w.drawnAt)||null,prizeLabel:String(w.prizeLabel||prizeLabel(w.profile&&w.profile.prizeType))}:null};}
function recalcGiveaway(state){const g=state.giveaway,eligible=countEligible(state);if(giveawayPhase(g)==='WAITING'&&eligible>=Number(g.minParticipants||10)){g.startedAt=now();g.endsAt=g.startedAt+roundDurationMs(g);addAudit(state,g.isTest?'test_giveaway_started':'giveaway_started',{roundNumber:g.roundNumber,eligible,isTest:!!g.isTest});}return eligible;}
function addAudit(s,type,data={}){s.audit.push({at:now(),type,data});s.audit=s.audit.slice(-2000);}
function auditActor(ss){if(!ss||!ss.twitch)return null;return {twitchUserId:String(ss.twitch.id||''),login:cleanTwitchLogin(ss.twitch.login),displayName:esc(ss.twitch.displayName||ss.twitch.login),role:isOwner(ss.twitch)?'owner':'admin'};}
function addAdminAudit(s,type,ss,data={}){addAudit(s,type,Object.assign({},data,{actor:auditActor(ss)}));}
function pointsAllowed(u){return !(u.pointsPausedUntil&&u.pointsPausedUntil>now());}
function applyPoints(state,u,amount,source){amount=Math.floor(Number(amount)||0);if(amount<=0)return {added:0,reason:'invalid'};if(isStaffUser(state,u))return {added:0,reason:'staff'};if(state.settings&&state.settings.globalPointsPaused)return {added:0,reason:'global_pause'};if(!accrualOpen(state))return {added:0,reason:'round_closed'};if(source!=='admin'&&!pointsAllowed(u))return {added:0,reason:'paused'};u.points+=amount;syncTickets(u,state.giveaway);u.updatedAt=now();addAudit(state,'points_added',{roundNumber:state.giveaway.roundNumber,twitchUserId:u.twitchUserId,amount,source});recalcGiveaway(state);return {added:amount,reason:'ok'};}
function addChatHistory(u,item){u.chatHistory.push(item);u.chatHistory=u.chatHistory.slice(-200);}
function processChatMessage(state,evt,{streamOnline=runtime.streamOnline,source='eventsub'}={}){
  const mid=String(evt.messageId||'').slice(0,200);if(mid&&state.processedMessages[mid])return {counted:false,reason:'duplicate'};if(mid)state.processedMessages[mid]=now();
  const u=getOrCreateChatUser(state,evt);const settings=state.settings;let counted=false,reason='';
  if(!settings.messagePointsEnabled)reason='message_points_disabled';
  else if(settings.globalPointsPaused)reason='global_pause';
  else if(!accrualOpen(state))reason='round_closed';
  else if(isStaffUser(state,u))reason='staff';
  else if(!pointsAllowed(u))reason='paused';
  else if(!streamOnline&&!settings.countMessagesOffline)reason='stream_offline';
  else if(Number(settings.chatCooldownSeconds||0)>0&&u.lastChatPointAt&&now()-u.lastChatPointAt<Number(settings.chatCooldownSeconds)*1000)reason='cooldown';
  else {const a=applyPoints(state,u,settings.pointsPerMessage,'chat');counted=a.added>0;if(counted)u.lastChatPointAt=now();reason=counted?(streamOnline?'online':'offline_test'):a.reason;}
  const row={at:now(),messageId:mid||id(8),text:String(evt.text||'').slice(0,500),counted,reason,streamOnline:!!streamOnline,source};addChatHistory(u,row);u.updatedAt=now();runtime.lastChatAt=row.at;return {counted,reason,user:privateUser(u),row};
}

function parseCookies(req){const out={};(req.headers.cookie||'').split(';').forEach(x=>{const i=x.indexOf('=');if(i>0)out[x.slice(0,i).trim()]=decodeURIComponent(x.slice(i+1));});return out;}
function saveSessions(){const obj={};for(const [sid,v] of sessions.entries()){if(v&&v.expiresAt>now())obj[sid]={twitch:v.twitch,createdAt:v.createdAt,expiresAt:v.expiresAt};}jsonWrite(SESSION_FILE,{version:1,sessions:obj});try{fs.chmodSync(SESSION_FILE,0o600)}catch{}}
function loadSessions(){sessions.clear();const raw=jsonRead(SESSION_FILE,{sessions:{}}),src=raw&&raw.sessions&&typeof raw.sessions==='object'?raw.sessions:{};for(const [sid,v] of Object.entries(src)){if(v&&v.twitch&&Number(v.expiresAt)>now())sessions.set(sid,{twitch:v.twitch,accessToken:'',createdAt:Number(v.createdAt)||now(),expiresAt:Number(v.expiresAt)});}try{fs.chmodSync(SESSION_FILE,0o600)}catch{}}
function sessionFor(req){const sid=parseCookies(req).sovara_session,s=sid&&sessions.get(sid);if(!s||s.expiresAt<now()){if(sid&&sessions.delete(sid))saveSessions();return null;}return s;}
function createSession(res,twitch,accessToken=''){const sid=id(32);sessions.set(sid,{twitch,accessToken:'',createdAt:now(),expiresAt:now()+7*86400000});saveSessions();res.setHeader('Set-Cookie',`sovara_session=${sid}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${7*86400}${isProduction()?'; Secure':''}`);return sid;}
function clearSession(req,res){const sid=parseCookies(req).sovara_session;if(sid&&sessions.delete(sid))saveSessions();res.setHeader('Set-Cookie',`sovara_session=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0${isProduction()?'; Secure':''}`);}
function isOwner(twitch,config=loadConfig()){if(!twitch)return false;if(config.adminTwitchUserId)return String(twitch.id)===String(config.adminTwitchUserId);return safeEqual(twitch.login,config.adminTwitchLogin);}
function managedAdminMatch(state,twitch){if(!state||!twitch)return null;const idv=String(twitch.twitchUserId||twitch.id||''),login=cleanTwitchLogin(twitch.login);return (state.admins||[]).find(a=>(a.twitchUserId&&String(a.twitchUserId)===idv)||safeEqual(a.login,login))||null;}
function isAdmin(twitch,config=loadConfig(),state=null){if(!twitch)return false;if(isOwner(twitch,config))return true;state=state||loadState();return !!managedAdminMatch(state,twitch);}
function isBroadcasterUser(u,config=loadConfig()){if(!u)return false;if(config.adminTwitchUserId&&String(u.twitchUserId||u.id||'')===String(config.adminTwitchUserId))return true;return safeEqual(u.login,config.adminTwitchLogin);}
function isStaffUser(state,u,config=loadConfig()){return isBroadcasterUser(u,config)||!!managedAdminMatch(state,u);}
function maybeBindAdmin(twitch){const c=loadConfig();if(!c.adminTwitchUserId&&safeEqual(twitch.login,c.adminTwitchLogin)){c.adminTwitchUserId=String(twitch.id);saveConfig(c);}}
function bindManagedAdmin(state,twitch){const a=managedAdminMatch(state,twitch);if(!a||isOwner(twitch))return false;a.twitchUserId=String(twitch.id);a.login=cleanTwitchLogin(twitch.login);a.displayName=esc(twitch.displayName||twitch.login);a.avatar=esc(twitch.avatar);return true;}
function sendJson(res,status,data){const body=JSON.stringify(data);res.writeHead(status,{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','Content-Length':Buffer.byteLength(body)});res.end(body);}
function sendText(res,status,text,type='text/plain; charset=utf-8'){res.writeHead(status,{'Content-Type':type,'Cache-Control':'no-store'});res.end(text);}
async function bodyJson(req){return new Promise((resolve,reject)=>{let b='';req.on('data',c=>{b+=c;if(b.length>1e6){reject(Error('body too large'));req.destroy();}});req.on('end',()=>{try{resolve(b?JSON.parse(b):{});}catch(e){reject(e);}});req.on('error',reject);});}
async function postForm(url,params){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(params)});const text=await r.text();let data;try{data=JSON.parse(text)}catch{data={message:text}}return {ok:r.ok,status:r.status,data};}

function loadAdminAuth(){return jsonRead(ADMIN_AUTH_FILE,null);}
function saveAdminAuth(auth){jsonWrite(ADMIN_AUTH_FILE,auth);try{fs.chmodSync(ADMIN_AUTH_FILE,0o600);}catch{}}
function clearAdminAuth(){try{fs.unlinkSync(ADMIN_AUTH_FILE);}catch{}}
async function exchangeAdminCode(code,redirectUri){const c=loadConfig();if(!c.clientSecret)throw Error('TWITCH_CLIENT_SECRET не настроен на сервере.');const r=await postForm('https://id.twitch.tv/oauth2/token',{client_id:c.clientId,client_secret:c.clientSecret,code,grant_type:'authorization_code',redirect_uri:redirectUri});if(!r.ok)throw Error(r.data&&r.data.message||'Twitch не выдал служебный токен.');return r.data;}
