async function ensureAdminToken(){if(runtime.adminToken&&runtime.adminTwitch&&(!runtime.adminTokenExpiresAt||runtime.adminTokenExpiresAt>now()+60000))return runtime.adminToken;await refreshPersistedAdminToken();return runtime.adminToken;}
async function restoreAdminRuntime(){const c=loadConfig(),auth=loadAdminAuth();runtime.adminAuthRestored=true;if(!auth||!auth.accessToken||!auth.twitch)return false;try{const granted=new Set(Array.isArray(auth.scope)?auth.scope:String(auth.scope||'').split(/\s+/));for(const need of ADMIN_SCOPES.split(/\s+/)){if(need&&!granted.has(need))throw Error('Twitch-службы нужно переподключить: требуется новое разрешение проверки фолловеров.');}let token=String(auth.accessToken),twitch=auth.twitch,expiresAt=Number(auth.expiresAt)||0;if(expiresAt&&expiresAt<=now()+60000){const x=await refreshPersistedAdminToken();token=x.accessToken;twitch=x.twitch;expiresAt=x.expiresAt;}else{const validated=await validateTwitchToken(token,c.clientId);if(!isOwner(validated,c))throw Error('Сохранённый Twitch token не принадлежит владельцу.');twitch=validated;setAdminRuntime(twitch,token,expiresAt,false);}startEventSub();refreshStreamStatus(true);startWatchtimeLoop();startFollowerSyncLoop(false);return true;}catch(e){runtime.adminToken='';runtime.adminTwitch=null;runtime.adminTokenExpiresAt=0;runtime.lastStreamError='Автовосстановление Twitch: '+e.message;return false;}}
async function validateTwitchToken(token,clientId){const r=await fetch('https://id.twitch.tv/oauth2/validate',{headers:{Authorization:`OAuth ${token}`}});if(!r.ok)throw Error('Twitch не подтвердил OAuth token.');const v=await r.json();if(String(v.client_id)!==String(clientId))throw Error('OAuth token выпущен для другого Client ID.');if(!v.user_id||!v.login)throw Error('Twitch не вернул пользователя.');let displayName=v.login,avatar='';try{const u=await fetch('https://api.twitch.tv/helix/users',{headers:{Authorization:`Bearer ${token}`,'Client-Id':clientId}});if(u.ok){const j=await u.json();if(j.data&&j.data[0]){displayName=j.data[0].display_name||displayName;avatar=j.data[0].profile_image_url||'';}}}catch{}return {id:String(v.user_id),login:String(v.login),displayName:String(displayName),avatar:String(avatar)};}
function requireAuth(req,res){const s=sessionFor(req);if(!s){sendJson(res,401,{error:'AUTH_REQUIRED'});return null;}return s;}
function requireAdmin(req,res){const ss=requireAuth(req,res);if(!ss)return null;if(!isAdmin(ss.twitch,loadConfig())){sendJson(res,403,{error:'ADMIN_REQUIRED'});return null;}return ss;}
function requireOwner(req,res){const ss=requireAuth(req,res);if(!ss)return null;if(!isOwner(ss.twitch,loadConfig())){sendJson(res,403,{error:'OWNER_REQUIRED',message:'Только владелец сайта может управлять администраторами и Twitch-службами.'});return null;}return ss;}

async function twitchApi(url,token,retried=false){const c=loadConfig();if(token===runtime.adminToken&&runtime.adminToken){try{token=await ensureAdminToken();}catch{}}const r=await fetch(url,{headers:{Authorization:`Bearer ${token}`,'Client-Id':c.clientId}});const text=await r.text();let data;try{data=JSON.parse(text)}catch{data={message:text}}if(r.status===401&&token===runtime.adminToken&&!retried){await refreshPersistedAdminToken();return twitchApi(url,runtime.adminToken,true);}if(!r.ok)throw Error(data.message||`Twitch API ${r.status}`);return data;}
async function refreshStreamStatus(force=false){if(!runtime.adminToken||!runtime.adminTwitch){runtime.streamStatus='NO_AUTH';runtime.streamOnline=false;return runtimeSummary();}if(!force&&now()-runtime.lastStreamCheck<15000)return runtimeSummary();runtime.lastStreamCheck=now();try{const d=await twitchApi(`https://api.twitch.tv/helix/streams?user_id=${encodeURIComponent(runtime.adminTwitch.id)}`,runtime.adminToken);const stream=d.data&&d.data[0];runtime.streamOnline=!!stream;runtime.streamStatus=stream?'ONLINE':'OFFLINE';runtime.streamStartedAt=stream?stream.started_at:null;runtime.lastStreamError='';}catch(e){runtime.streamStatus='ERROR';runtime.lastStreamError=e.message;}return runtimeSummary();}
async function fetchFollowerPage(after=''){if(!runtime.adminToken||!runtime.adminTwitch)throw Error('Нет Twitch авторизации для проверки фолловеров');await ensureAdminToken();const c=loadConfig(),u=new URL('https://api.twitch.tv/helix/channels/followers');u.searchParams.set('broadcaster_id',runtime.adminTwitch.id);u.searchParams.set('first','100');if(after)u.searchParams.set('after',after);return twitchApi(u.toString(),runtime.adminToken);}
function adminHasScope(scope){const a=loadAdminAuth();const granted=new Set(Array.isArray(a&&a.scope)?a.scope:String(a&&a.scope||'').split(/\s+/));return granted.has(scope);}
async function refreshFollowerCache(force=false){if(!runtime.adminToken||!runtime.adminTwitch){runtime.followerSyncError='Нет Twitch авторизации';return false;}if(!adminHasScope('moderator:read:followers')){runtime.followerSyncError='Нужно переподключить Twitch-службы: нет moderator:read:followers';return false;}if(!force&&runtime.followersLoadedAt&&now()-runtime.followersLoadedAt<FOLLOWER_CACHE_TTL)return true;if(followerRefreshPromise)return followerRefreshPromise;followerRefreshPromise=(async()=>{try{const fresh=new Set();let after='',pages=0,total=0;do{const d=await fetchFollowerPage(after);for(const x of d.data||[])fresh.add(String(x.user_id));total=Number(d.total)||total;after=d.pagination&&d.pagination.cursor||'';pages++;}while(after&&pages<2000);if(total>0&&fresh.size===0)throw Error('Twitch вернул только число фолловеров без списка — переподключи Twitch-службы с новым разрешением.');followerIds.clear();for(const x of fresh)followerIds.add(x);runtime.followersLoadedAt=now();runtime.followerCount=Number(total)||fresh.size;runtime.followerSyncError='';const st=loadState();for(const [uid,u0] of Object.entries(st.users)){const u=normalizeUser(u0);if(isStaffUser(st,u))continue;u.isFollower=followerIds.has(String(uid));u.followerCheckedAt=runtime.followersLoadedAt;}recalcGiveaway(st);saveState(st);return true;}catch(e){runtime.followerSyncError=e.message||String(e);return false;}finally{followerRefreshPromise=null;}})();return followerRefreshPromise;}
async function followerAllowed(userId){userId=String(userId||'');if(!userId)return null;if(runtime.adminTwitch&&userId===String(runtime.adminTwitch.id))return true;const ok=await refreshFollowerCache(false);if(!ok)return null;return followerIds.has(userId);}
function markFollowerUser(u,followed=true){if(!u)return;u.isFollower=!!followed;u.followerCheckedAt=now();}
function startFollowerSyncLoop(runNow=true){if(runtime.followerTimer){clearInterval(runtime.followerTimer);runtime.followerTimer=null;}if(!runtime.adminToken||!runtime.adminTwitch)return;if(runNow)refreshFollowerCache(true).catch(()=>{});runtime.followerTimer=setInterval(()=>{refreshFollowerCache(true).catch(()=>{});},FOLLOWER_SYNC_INTERVAL);}
function runtimeSummary(){return {appVersion:APP_VERSION,startedAt:PROCESS_STARTED_AT,uptimeSeconds:Math.max(0,Math.floor((Date.now()-PROCESS_STARTED_AT)/1000)),sessionsActive:sessions.size,websocketAvailable:!!WebSocket,eventSubStatus:runtime.wsStatus,chatSubscribed:runtime.chatSubscribed,streamSubscribed:runtime.streamSubscribed,streamStatus:runtime.streamStatus,streamOnline:runtime.streamOnline,streamStartedAt:runtime.streamStartedAt,lastStreamCheck:runtime.lastStreamCheck,lastStreamError:runtime.lastStreamError,lastChatAt:runtime.lastChatAt,lastWatchtimePoll:runtime.lastWatchtimePoll,lastWatchtimeUsers:runtime.lastWatchtimeUsers,lastWatchtimeError:runtime.lastWatchtimeError,adminRuntimeReady:!!runtime.adminToken,adminAuthStored:!!loadAdminAuth(),adminTokenExpiresAt:runtime.adminTokenExpiresAt||0,followSubscribed:!!runtime.followSubscribed,followersLoadedAt:runtime.followersLoadedAt||0,followerCount:runtime.followerCount||0,followerSyncError:runtime.followerSyncError||'',followerSyncEveryMinutes:Math.round(FOLLOWER_SYNC_INTERVAL/60000),backup:backupList()[0]||null};}
async function createEventSub(type,version,condition,sessionId){const c=loadConfig();await ensureAdminToken();const r=await fetch('https://api.twitch.tv/helix/eventsub/subscriptions',{method:'POST',headers:{Authorization:`Bearer ${runtime.adminToken}`,'Client-Id':c.clientId,'Content-Type':'application/json'},body:JSON.stringify({type,version,condition,transport:{method:'websocket',session_id:sessionId}})});const tx=await r.text();let d;try{d=JSON.parse(tx)}catch{d={message:tx}}if(!r.ok)throw Error(`${type}: ${d.message||r.status}`);return d;}
async function subscribeEventSub(sessionId){if(!runtime.adminTwitch||!runtime.adminToken)return;const bid=runtime.adminTwitch.id;runtime.chatSubscribed=false;runtime.streamSubscribed=false;runtime.followSubscribed=false;const errors=[];try{await createEventSub('channel.chat.message','1',{broadcaster_user_id:bid,user_id:bid},sessionId);runtime.chatSubscribed=true;}catch(e){errors.push(e.message);}try{await createEventSub('stream.online','1',{broadcaster_user_id:bid},sessionId);await createEventSub('stream.offline','1',{broadcaster_user_id:bid},sessionId);runtime.streamSubscribed=true;}catch(e){errors.push(e.message);}try{await createEventSub('channel.follow','2',{broadcaster_user_id:bid,moderator_user_id:bid},sessionId);runtime.followSubscribed=true;}catch(e){errors.push(e.message);}if(errors.length)runtime.lastStreamError=errors.join(' | ');}
function closeEventSub(){if(runtime.reconnectTimer){clearTimeout(runtime.reconnectTimer);runtime.reconnectTimer=null;}if(runtime.ws){try{runtime.ws.removeAllListeners();runtime.ws.close();}catch{}runtime.ws=null;}runtime.wsStatus='DISCONNECTED';runtime.wsSessionId='';runtime.chatSubscribed=false;runtime.streamSubscribed=false;runtime.followSubscribed=false;}
