function startEventSub(reconnectUrl=''){if(!WebSocket||!runtime.adminToken||!runtime.adminTwitch)return;closeEventSub();const url=reconnectUrl||'wss://eventsub.wss.twitch.tv/ws?keepalive_timeout_seconds=30';runtime.wsStatus='CONNECTING';const ws=new WebSocket(url);runtime.ws=ws;ws.on('open',()=>{runtime.wsStatus='CONNECTED';});ws.on('message',async raw=>{let msg;try{msg=JSON.parse(String(raw));}catch{return;}const kind=msg.metadata&&msg.metadata.message_type;if(kind==='session_welcome'){runtime.wsSessionId=msg.payload.session.id;await subscribeEventSub(runtime.wsSessionId);await refreshStreamStatus(true);}else if(kind==='session_reconnect'){const u=msg.payload&&msg.payload.session&&msg.payload.session.reconnect_url;if(u)startEventSub(u);}else if(kind==='notification'){const type=msg.metadata.subscription_type,e=msg.payload.event||{};if(type==='stream.online'){runtime.streamOnline=true;runtime.streamStatus='ONLINE';runtime.streamStartedAt=e.started_at||new Date().toISOString();runtime.lastStreamCheck=now();}else if(type==='stream.offline'){runtime.streamOnline=false;runtime.streamStatus='OFFLINE';runtime.streamStartedAt=null;runtime.lastStreamCheck=now();}else if(type==='channel.follow'){const uid=String(e.user_id||'');if(uid){followerIds.add(uid);runtime.followerCount=Math.max(runtime.followerCount||0,followerIds.size);const state=loadState(),existing=state.users[uid];if(existing){markFollowerUser(normalizeUser(existing),true);recalcGiveaway(state);saveState(state);}}}else if(type==='channel.chat.message'){const uid=String(e.chatter_user_id||'');if((await followerAllowed(uid))!==true)return;const state=loadState();const existing=state.users[uid];if(existing)markFollowerUser(normalizeUser(existing),true);processChatMessage(state,{userId:uid,login:e.chatter_user_login,displayName:e.chatter_user_name,messageId:e.message_id,text:e.message&&e.message.text||''},{streamOnline:runtime.streamOnline,source:'eventsub'});const created=state.users[uid];if(created)markFollowerUser(normalizeUser(created),true);saveState(state);}}});ws.on('close',()=>{if(runtime.ws===ws){runtime.ws=null;runtime.wsStatus='DISCONNECTED';runtime.chatSubscribed=false;runtime.streamSubscribed=false;scheduleReconnect();}});ws.on('error',e=>{runtime.wsStatus='ERROR';runtime.lastStreamError=e.message||'WebSocket error';});}
function setAdminRuntime(twitch,token,expiresAt=0,startServices=true){runtime.adminTwitch=twitch;runtime.adminToken=token||'';runtime.adminTokenExpiresAt=Number(expiresAt)||0;if(token&&startServices){startFollowerSyncLoop(true);startEventSub();refreshStreamStatus(true);startWatchtimeLoop();}}
async function fetchAllChatters(){if(!runtime.adminToken||!runtime.adminTwitch)return [];let after='',out=[];do{const url=new URL('https://api.twitch.tv/helix/chat/chatters');url.searchParams.set('broadcaster_id',runtime.adminTwitch.id);url.searchParams.set('moderator_id',runtime.adminTwitch.id);url.searchParams.set('first','1000');if(after)url.searchParams.set('after',after);const d=await twitchApi(url.toString(),runtime.adminToken);out=out.concat(d.data||[]);after=d.pagination&&d.pagination.cursor||'';}while(after&&out.length<10000);return out;}
async function runWatchtimePoll(){runtime.lastWatchtimePoll=now();runtime.lastWatchtimeUsers=0;runtime.lastWatchtimeError='';const initial=loadState();if(initial.settings.globalPointsPaused){runtime.lastWatchtimeError='Глобальная пауза — начисление остановлено';return;}if(!initial.settings.watchtimePointsEnabled){runtime.lastWatchtimeError='Начисление баллов за просмотр отключено';return;}if(!accrualOpen(initial)){runtime.lastWatchtimeError='Раунд закрыт — watchtime не начисляется';return;}if(!runtime.adminToken||!runtime.adminTwitch){runtime.lastWatchtimeError='Нет Twitch авторизации админа';return;}await refreshStreamStatus(true);if(!runtime.streamOnline){runtime.lastWatchtimeError='Стрим офлайн — watchtime не начислялся';return;}try{const followReady=await refreshFollowerCache(false);if(!followReady){runtime.lastWatchtimeError='Follow-проверка недоступна — watchtime не начислялся';return;}const chatters=await fetchAllChatters();const state=loadState(),mins=Math.max(1,Math.floor(Number(state.settings.watchtimePollMinutes)||5)),ppm=Math.max(0,Math.floor(Number(state.settings.pointsPerMinute)||1));if(!accrualOpen(state)){runtime.lastWatchtimeError='Раунд закрыт — watchtime не начисляется';return;}let updated=0;for(const c of chatters){const uid=String(c.user_id||'');if(!followerIds.has(uid))continue;const u=getOrCreateChatUser(state,{userId:uid,login:c.user_login,displayName:c.user_name});markFollowerUser(u,true);if(isBroadcasterUser(u)||!pointsAllowed(u))continue;const a=applyPoints(state,u,mins*ppm,'watchtime');if(a.added>0){u.totalWatchMinutes+=mins;updated++;}}runtime.lastWatchtimeUsers=updated;addAudit(state,'watchtime_poll',{roundNumber:state.giveaway.roundNumber,chatters:chatters.length,updated,minutes:mins});saveState(state);}catch(e){runtime.lastWatchtimeError=e.message;}}
function startWatchtimeLoop(){if(runtime.watchtimeTimer)clearInterval(runtime.watchtimeTimer);const state=loadState(),mins=Math.max(2,Math.min(30,Math.floor(Number(state.settings.watchtimePollMinutes)||5)));runtime.watchtimeTimer=setInterval(runWatchtimePoll,mins*60000);}

function staticFile(req,res,urlPath){
  if(urlPath==='/gift-icon.png'||urlPath==='/favicon.ico'||urlPath==='/apple-touch-icon.png'){
    res.writeHead(200,{'Content-Type':'image/png','Cache-Control':'public, max-age=31536000, immutable','Content-Length':GIFT_ICON.length});
    res.end(GIFT_ICON);return;
  }
  if(!['/','/index.html','/auth/callback'].includes(urlPath)){sendText(res,404,'Not found');return;}
  fs.stat(INDEX_FILE,(err,st)=>{if(err||!st.isFile()){sendText(res,404,'Not found');return;}res.writeHead(200,{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-cache'});fs.createReadStream(INDEX_FILE).pipe(res);});
}

