const server=http.createServer(async(req,res)=>{try{const u=new URL(req.url,'http://localhost');if(u.pathname==='/auth/callback'&&(u.searchParams.has('code')||u.searchParams.has('error')))return await handleAdminCodeCallback(req,res,u);if(u.pathname.startsWith('/api/'))return await api(req,res,u);staticFile(req,res,u.pathname);}catch(e){console.error(e);if(!res.headersSent)sendJson(res,500,{error:'INTERNAL',message:e.message});else res.end();}});
loadSessions();
const config=loadConfig();const listenPort=Number(process.env.PORT||config.port)||4177;const listenHost=process.env.HOST||'0.0.0.0';
function startServer(){
  console.log(`\n  SOVARA GIFT Web v${APP_VERSION}`);
  if(!WebSocket)console.log('  ⚠ Модуль ws не установлен: Twitch EventSub чат отключён. Запусти npm install.');
  if(!config.clientId)console.log('  Twitch Client ID пока не настроен в конфигурации сервера.');
  else console.log(`  Twitch OAuth: ${config.authMode} / Client ID ${config.clientId.slice(0,5)}…`);
  server.listen(listenPort,listenHost,()=>{
    console.log(`  Listening on ${listenHost}:${listenPort}`);
    console.log('  Публичные счётчики: локальная БД (без Twitch-запросов)');
    console.log('  Для остановки: Ctrl+C\n');
  });
  startBackupLoop();
  (async()=>{
    try{
      const restored=await restoreAdminRuntime();
      console.log(restored?'  Twitch-службы: восстановлены автоматически':'  Twitch-службы: сохранённой авторизации нет или её надо переподключить');
      if(restored&&runtime.adminToken){
        const synced=await refreshFollowerCache(true);
        console.log(synced?`  Follow-синхронизация: OK (${runtime.followerCount} фолловеров)`:`  Follow-синхронизация: ${runtime.followerSyncError||'не выполнена'}`);
        startFollowerSyncLoop(false);
      }
    }catch(e){console.log('  Twitch-службы: '+e.message);}
  })();
}
startServer();
